function botTactics(u,dt){let rank=u.team===1?aiLevel():5;if(rank>=5&&time>180){let ally=units.filter(v=>v!==u&&v.type==='hero'&&v.team===u.team&&alive(v)&&v.lastHit>time-2&&dist(v,u)<2400).sort((a,b)=>b.lastHit-a.lastHit)[0];if(ally&&dist(u,ally)>700){move(u,ally,dt);return true}}if(rank>=3&&!u.pendingCast&&!u.pendingAttack){let threat=shots.find(p=>p.source?.team!==u.team&&!p.homing&&!p.target&&p.dx!==undefined&&dist(p,u)<450&&((u.x-p.x)*p.dx+(u.y-p.y)*p.dy)>0&&Math.abs((u.x-p.x)*p.dy-(u.y-p.y)*p.dx)<70);if(threat){u.aiThreat??={id:threat.projectileId,seen:time};if(u.aiThreat.id!==threat.projectileId)u.aiThreat={id:threat.projectileId,seen:time};if(time-u.aiThreat.seen>Math.max(.06,.45-rank*.037)){move(u,{x:u.x-threat.dy*200,y:u.y+threat.dx*200},dt);return true}}else u.aiThreat=null}if(rank>=4&&u.hp/u.maxHp<.22){for(let id of ['heal','barrier'])if(u.summoners.includes(id)&&summoners.cooldown(u,id)===0)summoners.cast(u,id);if(rank>=7&&u.summoners.includes('flash')&&summoners.cooldown(u,'flash')===0&&units.some(v=>v.type==='hero'&&v.team!==u.team&&alive(v)&&dist(v,u)<300))summoners.cast(u,'flash',{x:u.x+Math.sign(base[u.team].x-u.x)*200,y:u.y+Math.sign(base[u.team].y-u.y)*200})}return false}
