function trackGold(u){let value=u.gold||0;Object.defineProperty(u,'gold',{enumerable:true,configurable:true,get:()=>value,set:n=>{let gain=n-value;value=n;if(gain>0&&!u.suppressGoldFloat){u.goldFloatPending=(u.goldFloatPending||0)+gain;if(gain>=1||time-(u.goldFloatAt||0)>=1){let amount=Math.floor(u.goldFloatPending);if(amount>0){let previous=floating.findLast(f=>f.goldOwner===u.id&&time-f.createdAt<.05);if(previous){previous.goldAmount+=amount;previous.text='◈ +'+previous.goldAmount;previous.life=1}else emitFloat({x:u.x,y:u.y-100,text:'◈ +'+amount,color:'#ffd46f',life:1,goldOwner:u.id,goldAmount:amount,createdAt:time});u.goldFloatPending-=amount;u.goldFloatAt=time}}}}});return u}
function hero(id,team,lane,isPlayer=false){
 const h=C.heroes[id];let u={id:++uid,type:'hero',hero:id,team,lane,player:isPlayer,x:base[team].x+(team?-430:430)+(team?1:-1)*(lane-1)*32,y:base[team].y+(team?430:-430)+lane*15,level:1,xp:0,gold:C.startingGold,items:[],cd:[0,0,0,0],attackCd:0,skillTimer:2+rand()*3,death:0,k:0,d:0,a:0,shield:0,shieldTime:0,guard:0,spin:0,spinTick:0,focus:0,boost:0,stun:0,root:0,slow:0,slowAmount:0,silence:0,invisible:0,invulnerable:0,phaseDelay:0,entropy:0,skillRanks:[0,0,0,0],skillPoints:1,recall:0,lastHit:-20,target:null,dest:null,angle:-Math.PI/4,...h};
 u.baseStats={hp:h.stats.hp,attack:h.stats.attack,armor:h.stats.armor,mr:h.stats.mr,speed:h.stats.speed,mana:h.stats.mana,ap:h.stats.ap||0,attackSpeed:h.stats.baseAS};u.maxHp=h.stats.hp;u.maxMana=h.stats.mana;u.hp=h.stats.hp;u.mp=h.stats.mana;u.bounty=C.bounty.initial;u.visualScale=id==='anvil'?C.tankVisualScale*1.15:['garen','sett','darius','illaoi','dva','zarya'].includes(id)?C.tankVisualScale:C.heroVisualScale;trackGold(u);if(!window.RIFT_TEST_RUNES_DISABLED)runeEffects?.init(u,RunePages.lockFor(id));summoners.init(u,isPlayer?selectedSummoners:['flash','heal']);recalc(u);modeRuntime?.init(u);itemEffects?.sync(u);if(!isPlayer)autoLearn(u);units.push(u);return u;
}
function structure(team,lane,t,kind,tier=0){let p=kind==='nexus'?base[team]:C.map.towerPoint(lane,team,tier),v=kind==='nexus'?C.nexus:{...C.tower,...C.towerTiers[tier]};return{id:++uid,type:kind,team,lane,tier,...p,maxHp:v.hp,hp:v.hp,attack:v.attack,range:kind==='nexus'?v.range*2.5:v.range,interval:v.interval,attackCd:0,armor:v.armor,mr:v.mr,name:kind==='nexus'?'水晶':v.name,plates:[],armorPenPct:kind==='tower'?(C.towerArmorPenPct??.3):0,radius:kind==='tower'?C.tower.radius*(C.towerSizeMultiplier??1.75):v.radius,modelScale:kind==='tower'?C.tower.modelScale*(C.towerSizeMultiplier??1.75):C.nexus.modelScale,visualScale:kind==='nexus'?C.nexus.modelScale:1}}

