function spawnARAMStructures(){for(let team=0;team<2;team++){let a=C.aram,n=structure(team,0,0,'nexus');Object.assign(n,GameModes.toWorld(a.nexus_positions[team]));units.push(n);for(let tier=0;tier<4;tier++){let t=structure(team,0,0,'tower',Math.min(tier,2));Object.assign(t,GameModes.toWorld(a.tower_positions[team][tier]),{tier,name:tier===0?'桥头外塔':tier===1?'内塔':'水晶守卫塔',range:t.range*(a.tower_range_multiplier??1)});units.push(t)}let hp=C.towerTiers[1].hp;units.push({id:++uid,type:'inhibitor',name:'水晶兵营',team,lane:0,...GameModes.toWorld(a.inhibitor_positions[team]),hp,maxHp:hp,armor:C.towerTiers[1].armor,mr:C.towerTiers[1].mr,radius:65,attack:0,attackCd:Infinity,modelScale:1,angle:0})}}
function waveSpawnPoint(lane,team,i){
 let path=paths[lane],total=path.slice(1).reduce((n,p,j)=>n+dist(path[j],p),0),spacing=C.minionSpawnSpacing;
 // Keep the formation outside the enlarged nexus, including super-minion clearance.
 let nexus=units.find(u=>u.type==='nexus'&&u.team===team),start=GameModes.isARAM()?spacing:Math.ceil(((nexus?.radius||0)+37.5+8)/spacing)*spacing,distance=start;
 for(let j=0;j<=i;j++){if(j)distance+=spacing;let p;for(let attempt=0;attempt<80;attempt++,distance+=25){p=pointAt(path,team===0?distance/total:1-distance/total);if(!blocked(p.x,p.y,37.5))break}if(j===i)return p}
}
function spawnARAMWave(){if(time<aramWaveNext)return;let a=C.aram;wave++;aramWaveNext=time+(time>=a.late_wave_time?a.late_wave_interval:a.wave_interval);for(let team=0;team<2;team++){let superWave=units.some(u=>u.type==='inhibitor'&&u.team!==team&&!alive(u));for(let i=0;i<a.minion_count+(superWave?1:0);i++){let superMinion=i===a.minion_count,siege=!superMinion&&i===a.minion_count-1&&wave%3===0,p=waveSpawnPoint(0,team,i),hp=(C.minion.hp+wave*a.minion_hp_growth)*(superMinion?3:siege?1.8:1);units.push({id:++uid,type:'minion',team,lane:0,...p,hp,maxHp:hp,armor:C.minion.armor*(superMinion?2:1),mr:(C.minion.mr||15)*(superMinion?2:1),attack:(C.minion.attack+wave*2)*(superMinion?3:siege?1.5:1),speed:C.minion.speed*(1+Math.min(.5,wave*a.minion_speed_growth)),range:i>=3&&!superMinion?210:65,interval:1.2,attackCd:0,gold:superMinion?120:C.minion.gold,waypoint:team===0?1:paths[0].length-2,angle:0,superMinion,siege,radius:superMinion?37.5:30,visualScale:C.minionVisualScale*(superMinion?1.25:1)})}}}
function renderARAMSelection(){let box=$('aramSelection'),s=GameModes.selection;if(!s)return;box.innerHTML='<strong>你的随机英雄卡</strong><div class="aram-cards">'+s.offers.map(id=>'<button data-aram-pick="'+id+'" aria-pressed="'+(id===s.chosen)+'">'+C.heroes[id].name+'</button>').join('')+'</div><p>已选：'+C.heroes[s.chosen].name+' · 队友：'+s.allies.map(id=>C.heroes[id].name).join('、')+'</p><strong>团队候选池</strong><div class="aram-bench">'+s.bench.map(id=>'<button data-aram-pick="'+id+'">'+C.heroes[id].name+'</button>').join('')+'</div><p>每队英雄不重复；点击候选池可与当前英雄交换。队友可在下方与候选英雄交换。</p><div class="aram-trades">'+s.allies.map((id,i)=>'<label>'+C.heroes[id].name+' 换用 <select data-aram-trade="'+i+'"><option value="">选择候选英雄</option>'+s.bench.map(x=>'<option value="'+x+'">'+C.heroes[x].name+'</option>').join('')+'</select></label>').join('')+'</div>';document.querySelectorAll('[data-aram-pick]').forEach(b=>b.onclick=()=>{if(GameModes.choose(b.dataset.aramPick)){selected=GameModes.selection.chosen;renderARAMSelection();setup()}});document.querySelectorAll('[data-aram-trade]').forEach(b=>b.onchange=()=>{let i=+b.dataset.aramTrade,id=b.value;if(!s.bench.includes(id))return;s.bench=s.bench.filter(x=>x!==id);s.bench.push(s.allies[i]);s.allies[i]=id;renderARAMSelection();setup()})}
