function recalc(u){mechanics.recalc(u)}

function maxLevel(u){return u.maxLevel||18}
function rankValue(value,rank){return Array.isArray(value)?value[Math.max(0,rank-1)]:value}
function skillValue(u,i,k){return rankValue(u.skills[i][k],u.skillRanks[i])}
function canLearn(u,i){if(u.skillPoints<=0)return false;let rank=u.skillRanks[i];return rank<u.skills[i].maxRank&&u.level>=(i===3?[6,11,16][rank]:rank*2+1)}
function learn(u,i){if(u.player&&state!=='playing')return false;if(!canLearn(u,i))return false;u.skillRanks[i]++;u.skillPoints--;mechanics.onLearn(u,i);if(u.player){beep(720,.08);updateHUD();toast(u.skills[i].name+' · '+u.skillRanks[i]+' 级')}return true}
function autoLearn(u){while(u.skillPoints>0){let i=[3,0,1,2].find(i=>canLearn(u,i));if(i===undefined)break;learn(u,i)}}
function gainXp(u,xp){if(u.level>=maxLevel(u))return;u.xp+=xp*(C.experienceMultiplier||1)*(GameModes.isARAM()?C.aram.kill_xp_multiplier:1);let needed=u.level*120;while(u.xp>=needed&&u.level<maxLevel(u)){u.xp-=needed;u.level++;recalc(u);u.skillPoints++;if(!u.player)autoLearn(u);needed=u.level*120;if(u.player){toast('等级提升 · Lv. '+u.level+(u.skillPoints?' · 可升级技能':''));ring(u.x,u.y,100,'#e7cf83',.8)}}}
function addEntropy(u,n){if(u?.hero==='zero'&&n>0){ZeroGrowth.set(u,u.entropy+n,i=>{mechanics.core.emit('EvolutionUnlocked',u,u,{abilityId:i,threshold:C.zeroEvolution.thresholds[i]});if(u.player)toast('熵增进化 · '+'QWER'[i])});if(u.player)emitFloat({x:u.x,y:u.y-60,text:'熵增 +'+n,color:'#67f5d2',life:1})}}
function brushAt(u){let old=brushCache.get(u);if(old&&old.x===u.x&&old.y===u.y&&old.revision===C.map.revision)return old.id;let id=C.map.bushes.find(b=>C.map.brushContains?C.map.brushContains(b,u.x,u.y):Math.abs(u.x-b.x)<b.w/2&&Math.abs(u.y-b.y)<b.h/2)?.id??-1;brushCache.set(u,{x:u.x,y:u.y,id,revision:C.map.revision});return id}
function visibleTo(u,v){if(!alive(v))return false;if(v.team===u.team)return true;if(v.type==='ward')return !!runeEffects?.canSeeWard(u.team,v);let cached=visionCache.get(u.team+':'+v.id);if(cached?.visible&&cached.x===v.x&&cached.y===v.y&&cached.hit===v.lastHit&&!(v.invisible>0))return true;if(summoners?.reveal(u.team,v))return true;if(v.invisible>0)return false;if(runeEffects?.reveal?.(u.team,v)||mechanics.reveal(u.team,v))return true;let key=u.team+':'+v.id,old=visionCache.get(key);if(old&&old.x===v.x&&old.y===v.y&&old.hit===v.lastHit)return old.visible;let bush=brushAt(v),sources=visionSourcesFor(u.team),visible=sources.some(a=>dist(a,v)<(a.type==='hero'?1400:a.type==='minion'?850:1200)&&(!C.map.lineOfSight||C.map.lineOfSight(a,v))&&(bush<0||brushAt(a)===bush||dist(a,v)<100||time-v.lastHit<2));if(!visible&&bush>=0&&C.map.faelights)for(let f of C.map.faelights){let ward=runeEffects?.wards?.().some(w=>w.team===u.team&&alive(w)&&brushAt(w)===f.brushId);if(ward&&dist(v,f)<f.radius&&(!C.map.lineOfSight||C.map.lineOfSight(f,v)))visible=true}visionCache.set(key,{x:v.x,y:v.y,hit:v.lastHit,visible});return visible}
function towerProtected(u){if(GameModes.isARAM())return modeRuntime.structureProtected(u);if(u.type==='inhibitor')return units.some(v=>v.type==='tower'&&v.team===u.team&&v.lane===u.lane&&v.tier<3&&alive(v));if(u.type==='tower'&&u.tier===3)return !units.some(v=>v.type==='inhibitor'&&v.team===u.team&&!alive(v));return u.type==='tower'&&units.some(v=>v.type==='tower'&&v.team===u.team&&v.lane===u.lane&&v.tier<u.tier&&alive(v))}
function splitGold(target,amount,reason){let recipients=units.filter(v=>v.type==='hero'&&v.team!==target.team&&v.team<2&&alive(v)&&dist(v,target)<=C.rewardRadius);if(!recipients.length)return;for(let h of recipients){h.gold+=amount/recipients.length;if(h.player){toast(reason+' · '+Number((amount/recipients.length).toFixed(1))+' 金币')}}}
