function nearestEnemy(u,range,heroesOnly=false){return mechanics.nearest(u,range,v=>v.team!==u.team&&(!heroesOnly||v.type==='hero')&&canBeTarget(u,v))}
function nexusProtected(team){if(GameModes.isARAM())return modeRuntime.structureProtected({type:'nexus',team});return units.some(v=>v.type==='tower'&&v.team===team&&v.tier===3&&alive(v))||![0,1,2].some(l=>!units.some(v=>v.type==='tower'&&v.team===team&&v.lane===l&&v.tier<3&&alive(v)))}
function enemyStructures(u){if(GameModes.isARAM())return units.filter(v=>v.team!==u.team&&alive(v)&&['tower','nexus','inhibitor'].includes(v.type)&&!modeRuntime.structureProtected(v)).sort((a,b)=>dist(u,a)-dist(u,b));return units.filter(v=>v.team!==u.team&&alive(v)&&(['tower','inhibitor'].includes(v.type)&&v.lane===u.lane&&!towerProtected(v)||v.type==='nexus'&&!nexusProtected(v.team))).sort((a,b)=>dist(u,a)-dist(u,b))}
function emitFx(data){fx.push(effectPool.acquire(data))}
function emitFloat(data){floating.push(numberPool.acquire(data))}
