  if(source?.type==='hero'&&source.team!==u.team){source.k++;source.gold+=u.bounty??C.bounty.initial;source.bounty=Math.min(C.bounty.maximum,(source.bounty??C.bounty.initial)+C.bounty.killBonus);let participation={killId:u.id+':'+(u._life||0),kind:'kill'};itemEffects?.onTakedown(source,u,participation);mechanics.core.emit('ChampionTakedown',source,u,participation);if(!firstBlood){firstBlood=true;source.gold+=C.firstBloodBonus;if(source.player)toast('第一滴血 · 额外 100 金币');feed.push({t:time,text:'第一滴血 · '+source.name,color:teamColor[source.team]})}addEntropy(source,source.passive?.heroKill||0);gainXp(source,C.heroKillExperience??50)}
  for(let h of units.filter(v=>v.type==='hero'&&v.team!==u.team&&v!==source&&((u.attackers?.[v.id]??-99)>time-(v.hero==='genji'?C.heroParams.genji.P.suggested_assist_window:8)))){h.a++;h.gold+=100;let participation={killId:u.id+':'+(u._life||0),kind:'assist'};itemEffects?.onTakedown(h,u,participation);mechanics.core.emit('ChampionTakedown',h,u,participation);addEntropy(h,h.passive?.assist||0);gainXp(h,70)}
  u.bounty=Math.max(C.bounty.minimum,Math.floor((u.bounty??C.bounty.initial)*C.bounty.deathMultiplier));feed.push({t:time,text:(source?.name||(source?.type==='tower'?'防御塔':'小兵'))+' ⚔ '+u.name,color:teamColor[1-u.team]});if(u.player){stopAttack();beep(130,.4)}
