function updateEquipmentUI(){if(!player)return;let active=player.items.filter(id=>C.itemParams[id]?.active_type&&C.itemParams[id].active_type!=='none'),signature=active.join('|'),box=$('itemActives');if(signature!==equipmentSignature){equipmentSignature=signature;box.innerHTML=active.map((id,i)=>'<button data-active-item="'+id+'" title="'+escapeConfigText(ItemSystem.get(id).desc)+'"><b>'+itemIcon(ItemSystem.get(id))+'</b><small>'+ItemSystem.get(id).name+'</small><em></em><kbd>'+('567890'[i])+'</kbd></button>').join('');document.querySelectorAll('[data-active-item]').forEach(b=>{let id=b.dataset.activeItem;b.addEventListener('pointerdown',e=>{if(state!=='playing')return;e.preventDefault();e.stopPropagation();b.setPointerCapture(e.pointerId);equipmentAim={id,startX:e.clientX,startY:e.clientY,dragged:false,point:{...pointer}}});b.addEventListener('pointermove',e=>{let a=equipmentAim;if(!a||a.id!==id)return;let dx=e.clientX-a.startX,dy=e.clientY-a.startY;if(Math.hypot(dx,dy)>12){a.dragged=true;let p=C.itemParams[id],angle=Math.atan2(dy/(render3d?.groundYScale||1),dx),range=p.range||p.projectile_range||p.radius||300;a.point={x:player.x+Math.cos(angle)*range*Math.min(1,Math.hypot(dx,dy)/100),y:player.y+Math.sin(angle)*range*Math.min(1,Math.hypot(dx,dy)/100)};}});b.addEventListener('pointerup',e=>{let a=equipmentAim;if(!a||a.id!==id)return;equipmentAim=null;b.itemPointerAt=performance.now();if(Math.hypot(e.clientX-a.startX,e.clientY-a.startY)>220)return;useEquipment(id,a.dragged?a.point:id==='KNIGHTS_VOW'?{}:pointer)});b.onclick=()=>{if(b.itemPointerAt!=null&&performance.now()-b.itemPointerAt<500)return;useEquipment(id,id==='KNIGHTS_VOW'?{}:pointer)};for(let type of ['pointercancel','lostpointercapture'])b.addEventListener(type,()=>{equipmentAim=null})})}document.querySelectorAll('[data-active-item]').forEach(b=>{let cd=itemEffects.activeCooldown(player,b.dataset.activeItem);b.querySelector('em').textContent=cd>0?(Number.isFinite(cd)?Math.ceil(cd):'已耗尽'):'';b.classList.toggle('cooldown',cd>0);b.setAttribute('aria-label',ItemSystem.get(b.dataset.activeItem).name+(cd>0?' 冷却 '+Math.ceil(cd)+' 秒':' 已就绪'))});}
