function toggleShop(){if(state!=='playing')return;$('shop').classList.toggle('hidden');renderShop()}
let shopUndo=[],shopOwnedSignature='';
function copyShopState(v,seen=new Map()){if(!v||typeof v!=='object'||v.type&&v.id!=null)return v;if(seen.has(v))return seen.get(v);let out=Array.isArray(v)?[]:{};seen.set(v,out);for(let[k,x]of Object.entries(v))out[k]=copyShopState(x,seen);return out}
function invalidateShopUndo(){shopUndo=[];if($('undoPurchase'))$('undoPurchase').disabled=true}
function invalidatesShopUndo(e){return player&&(e.sourceId===player.id||e.type==='DamageApplied'&&e.targetId===player.id)&&['AbilityCastStarted','AbilityCommitted','DamageApplied'].includes(e.type)&&!(e.type==='DamageApplied'&&!(e.amount>0||e.absorbed>0))}
function checkShopUndo(){let last=shopUndo.at(-1);if(last&&(!canShop()||last.player!==player||last.after!==player.items.join('|')||mechanics.core.history().some(e=>e.id>last.eventId&&invalidatesShopUndo(e))))invalidateShopUndo();return shopUndo.length>0}
function undoPurchase(){if(!checkShopUndo()){toast('当前购买已无法撤回');return false}let entry=shopUndo.pop();player.items=entry.items.slice();player.gold+=entry.refund;player.itemState=copyShopState(entry.itemState);if(player.runeState){player.runeState.jackStacks=entry.jackStacks;player.runeState.jackAdaptive=entry.jackAdaptive}player.shields=entry.shields.filter(x=>x.until>time).map(x=>({...x}));sellIndex=null;recalc(player);itemEffects.cleanup(player);lastInventory=null;shopBuilt=false;updateHUD();renderShop();toast('已撤回购买 '+entry.name);return true}
function renderOwnedShop(){checkShopUndo();let key=player.items.join('|')+':'+canShop();if(key!==shopOwnedSignature){shopOwnedSignature=key;$('shopOwnedSlots').innerHTML=Array.from({length:6},(_,i)=>{let it=ItemSystem.get(player.items[i]);return it?'<button data-shop-sell="'+i+'" '+(!canShop()?'disabled':'')+' title="点击出售 '+escapeConfigText(it.name)+'" aria-label="出售 '+escapeConfigText(it.name)+'">'+itemIcon(it)+'<span>'+escapeConfigText(it.name)+'</span><small>售出 ◈ '+Math.floor(it.cost*(it.sellRatio??.7))+'</small></button>':'<div class="shop-owned-empty">空装备栏</div>'}).join('');document.querySelectorAll('[data-shop-sell]').forEach(b=>b.onclick=()=>{sellIndex=Number(b.dataset.shopSell);confirmSell()})}$('undoPurchase').disabled=!shopUndo.length;$('undoPurchase').onclick=undoPurchase;$('undoHint').textContent=shopUndo.length?'可撤回最近购买；使用技能、造成/受到伤害或离开购买范围后失效':'暂无可撤回的购买'}
function buy(id){if(!trainingActive()&&runeEffects?.canBuy(player,ItemSystem.get(id))===false){toast('符文限制：目前无法购买该物品');return false}checkShopUndo();let before={player,items:player.items.slice(),itemState:copyShopState(player.itemState),shields:(player.shields||[]).map(x=>({...x})),jackStacks:player.runeState?.jackStacks,jackAdaptive:player.runeState?.jackAdaptive},goldBefore=player.gold;let result=ItemSystem.buy(player,id,{canShop:canShop(),time,recalc});if(!result.ok){toast(result.reason);return false}runeEffects?.onPurchase?.(player,result.item);shopUndo.push({...before,after:player.items.join('|'),refund:goldBefore-player.gold,name:result.item.name,eventId:mechanics.core.history().at(-1)?.id||0});if(shopUndo.length>20)shopUndo.shift();itemEffects.cleanup(player);shopBuilt=false;lastInventory=null;updateHUD();renderShop();toast('已购买 '+result.item.name);beep(800,.1);return true}
// V19 装备预约：返回预约大件的购买计划。整件买得起就买整件，否则推荐当前买得起、价值最高的缺失组件。
function reservePlan(u){let id=u?.reservedItem,it=id&&ItemSystem.get(id);if(!it)return null;if(u.items.includes(id))return{item:it,done:true,missing:[],next:null};
 let used=new Set,missing=[];const own=part=>{let n=u.items.findIndex((x,i)=>!used.has(i)&&x===part);if(n>=0){used.add(n);return true}return false};
 const walk=(part,depth)=>{if(own(part))return;let c=ItemSystem.get(part);missing.push({id:part,depth});for(let p of c?.components||[])walk(p,depth+1)};for(let p of it.components||[])walk(p,1);
 let ctx={canShop:true,time},full=ItemSystem.validatePurchase(u,id,ctx),quote=ItemSystem.quote(u,id),value=it.cost-quote.cost;
 let next=full.ok?{id,cost:quote.cost}:null;if(!next){let best=null;for(let m of missing){let q=ItemSystem.quote(u,m.id),ok=ItemSystem.validatePurchase(u,m.id,ctx).ok;if(ok&&(!best||q.cost>best.cost))best={id:m.id,cost:q.cost}}next=best}
 let direct=missing.filter(m=>m.depth===1);return{item:it,done:false,missing,direct,next,remaining:quote.cost,progress:value/it.cost}}
let reserveSignature='';
function renderReserve(){let box=$('reservePanel');if(!box||!player)return;let plan=reservePlan(player);if(plan?.done){toast('预约装备已合成：'+plan.item.name);player.reservedItem=null;plan=null}
 let shop=canShop(),sig=!plan?'none':[plan.item.id,player.items.join(','),Math.floor(player.gold/25),shop,plan.next?.id].join('|');if(sig===reserveSignature)return;reserveSignature=sig;
 if(!plan){box.classList.add('hidden');box.innerHTML='';return}box.classList.remove('hidden');let it=plan.item,nx=plan.next&&ItemSystem.get(plan.next.id);
 let action=!nx?'<button class="reserve-buy" disabled>金币不足 · 还差 '+Math.max(0,Math.ceil(Math.min(...[plan.remaining,...plan.missing.map(m=>ItemSystem.quote(player,m.id).cost)])-player.gold))+'</button>':!shop?'<button class="reserve-buy" disabled>回泉水购买 '+nx.name+'</button>':'<button class="reserve-buy" data-reserve-buy="'+nx.id+'">'+(nx.id===it.id?'合成 ':'购买 ')+nx.name+' · '+plan.next.cost+'</button>';
 box.innerHTML='<div class="reserve-head">'+itemIcon(it)+'<div><small>预约装备</small><b>'+it.name+'</b><i style="--p:'+Math.round(plan.progress*100)+'%"></i></div><button class="reserve-x" data-reserve-cancel aria-label="取消预约">×</button></div>'+action+(plan.direct.length?'<div class="reserve-parts">'+plan.direct.map(m=>{let c=ItemSystem.get(m.id),q=ItemSystem.quote(player,m.id).cost;return'<button data-reserve-buy="'+m.id+'" title="'+c.name+' · '+q+'" '+(shop&&player.gold>=q?'':'class="poor"')+'>'+itemIcon(c)+'<small>'+q+'</small></button>'}).join('')+'</div>':'');
 box.querySelectorAll?.('[data-reserve-buy]')?.forEach(b=>b.onclick=e=>{e.stopPropagation();if(buy(b.dataset.reserveBuy)){reserveSignature='';renderReserve()}});let x=box.querySelector?.('[data-reserve-cancel]');if(x)x.onclick=e=>{e.stopPropagation();player.reservedItem=null;reserveSignature='';renderReserve()}}
function energyCostOf(u,i){let c=C.heroParams[u.hero]?.['QWER'[i]]?.energy_cost;if(Array.isArray(c))c=c[Math.min(c.length,Math.max(1,u.skillRanks?.[i]||1))-1];return Number.isFinite(c)?c:0}
