 let rec=ItemSystem.recommended(player.hero),items=C.items.filter(it=>!it.shopHidden&&(shopCategory==='all'||shopCategory==='recommended'&&rec.includes(it.id)||it.category===shopCategory||it.tier===shopCategory));
