 let a=pointAt(path,clamp(target-.01,0,1)),b=pointAt(path,clamp(target+.01,0,1)),tx=b.x-a.x,ty=b.y-a.y,tl=Math.hypot(tx,ty)||1,px=-ty/tl,py=tx/tl;
