function saveCheckpoint(){if(state!=='playing'&&state!=='paused')return false;return MatchCheckpoint.save({modeId:selectedMode,modeState:modeRuntime.exportState(),configVersion:window.ConfigRuntime?.version,configSnapshot:window.ConfigRuntime?.snapshot,trainingState:trainingActive()?{...training}:null,selected,difficulty,units,shots,fx,floating,feed,kills,playerId:player.id,uid,time,wave,rngSeed,firstBlood,mechanics:mechanics.exportState(),runes:runeEffects?.exportState(),jungle:jungle?.exportState(),clockTick:simulationClock.tick})}
function resumeCheckpoint(){let saved=MatchCheckpoint.load();if(saved&&saved.units?.some(u=>typeof u.hp!=='number'||!Number.isFinite(u.hp)||!Number.isFinite(u.maxHp))){console.error('[CombatValidation] Rejected corrupt checkpoint health');toast('上次对局含无效生命数据，请开始新对局');return}if(saved&&window.ConfigRuntime&&!ConfigRuntime.resume(saved))return;if(!saved||!C.heroes[saved.selected]||!Array.isArray(saved.units)||!Number.isFinite(saved.time))return;selectedMode=saved.modeId||'SR';if(saved.trainingState)Object.assign(training,saved.trainingState);selected=saved.selected;difficulty=saved.difficulty;setup();units=saved.units;shots=saved.shots;fx=saved.fx;floating=saved.floating;feed=saved.feed;kills=saved.kills;player=units.find(u=>u.id===saved.playerId);if(!player){lobby();return}uid=saved.uid;time=saved.time;wave=saved.wave;rngSeed=saved.rngSeed;firstBlood=saved.firstBlood;simulationClock.tick=saved.clockTick;simulationClock.time=time;simulationClock.accumulator=0;for(let u of units)if(u.type==='tower'&&u.tier<3)Object.assign(u,C.map.towerPoint(u.lane,u.team,u.tier));modeRuntime.restore(saved.modeState);mechanics.restoreState(saved.mechanics);runeEffects?.restoreState(saved.runes);jungle?.restore(saved.jungle);for(let u of units)if(u.type==='hero'){trackGold(u);u.bounty??=C.bounty.initial;let h=C.heroes[u.hero];u.stats=h.stats;u.passive=h.passive;u.skills=h.skills.map(s=>({...s}));u.maxLevel=18;if(u.hero==='khazix'){if(u.championState?.evolutions?.[0])u.skills[0].range+=C.heroParams.khazix.Q.evolve_range_bonus;if(u.championState?.evolutions?.[2])u.skills[2].range+=250}mechanics.recalc(u);if(u.hero==='zero')ZeroGrowth.sync(u)}state='paused';checkpointAt=time;camera={x:player.x,y:player.y};$('lobby').classList.add('hidden');$('pause').classList.remove('hidden');updateHUD();toast('对局已恢复 · 熵增、进化、冷却及飞行技能已还原')}
