function frame(stamp){perfSample139(stamp);if(!frameMetrics.windowStart)frameMetrics.windowStart=stamp;frameMetrics.frames++;if(stamp-frameMetrics.windowStart>=1000){frameMetrics.fps=frameMetrics.frames*1000/(stamp-frameMetrics.windowStart);canvas.dataset.diagnostics=JSON.stringify({...performanceSummary139(),targetFps:120,fps:Number(frameMetrics.fps.toFixed(1)),logicHz:60,meanLogicMs:frameMetrics.logicSteps?Number((frameMetrics.logicMs/frameMetrics.logicSteps).toFixed(3)):0,units:units.length,draw:render3d?.stats(),engine:mechanics.core.stats()});$('fpsStatus').textContent=Math.round(frameMetrics.fps)+' FPS';$('fpsStatus').style.color=frameMetrics.fps>=110?'#a7e4c4':frameMetrics.fps>=80?'#e2c389':'#ee8d8d';frameMetrics.frames=0;frameMetrics.windowStart=stamp;frameMetrics.logicMs=frameMetrics.logicSteps=0}let dt=last?Math.max(0,(stamp-last)/1000):0;last=stamp;if(state==='playing')update(dt);else simulationClock.accumulator=0;if(performance.now()>toastUntil)$('toast').classList.remove('show');draw();requestAnimationFrame(frame)}
mechanics=createChampionMechanics({nextId:()=>++uid,units:()=>units,shots:()=>shots,time:()=>time,state:()=>state,random:rand,teamColor,movingIntent:()=>!!(joystick.x||joystick.y||keys.ArrowLeft||keys.ArrowRight||keys.ArrowUp||keys.ArrowDown),movementAngle:u=>{let x=joystick.x+(keys.ArrowRight?1:0)-(keys.ArrowLeft?1:0),y=joystick.y+(keys.ArrowDown?1:0)-(keys.ArrowUp?1:0);return u.player&&(x||y)?Math.atan2(y,x):undefined},canTarget:canBeTarget,teamCanSee:(team,t)=>{let ally=units.find(u=>u.type==='hero'&&u.team===team&&alive(u));return ally?visibleTo(ally,t):false},targetFor,blocked,visibleTo,entropy:addEntropy,die,plates:towerPlates,toast,line,ring,float:(u,text,color,options)=>floating.push({x:u.x,y:u.y-30,text,color,life:.75,...options}),spinSlash:(u,r)=>fx.push({type:'dariusSlash',source:u,x:u.x,y:u.y,r,color:'#d94148',life:.35,max:.35}),protected:u=>trainingActive()&&training.invincible&&u===player||towerProtected(u)||u.type==='nexus'&&nexusProtected(u.team),announcement:(u,n)=>{feed.push({t:time,text:(u.team===player?.team?'我方':'敌方')+'空之律者已获得强化审判！ +'+n,color:u.team===player?.team?'#75c4ff':'#ff727e'});beep(490,.14)},warning:(u,p,range,width,life)=>{let a=Math.atan2(p.y-u.y,p.x-u.x);fx.push({type:'warning',x:u.x,y:u.y,tx:u.x+Math.cos(a)*range,ty:u.y+Math.sin(a)*range,color:'#e8b8ff',width,life,max:life,castId:u.pendingCast?.event?.castId})},areaWarning:(p,r,life,color)=>fx.push({type:'area',x:p.x,y:p.y,r,color,life,max:life})});
